html:
{% set token = frappe.get_doc('BBF Token', doc.token_number) if doc.token_number else None %}
<style>
.ge-print { font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto; padding: 10px; }
.ge-print .header { background: #1a3a5c; color: #fff; padding: 12px 20px; text-align: center; border-radius: 6px 6px 0 0; }
.ge-print .header h2 { margin: 0; font-size: 18px; letter-spacing: 1px; }
.ge-print .header p { margin: 2px 0 0; font-size: 11px; opacity: 0.8; }
.ge-print .subheader { background: #f0f4f8; padding: 10px 20px; text-align: center; border: 1px solid #ddd; border-top: 0; }
.ge-print .subheader h3 { margin: 0; color: #e74c3c; font-size: 16px; }
.ge-print .body { border: 1px solid #ddd; border-top: 0; padding: 15px 20px; }
.ge-print table.info { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
.ge-print table.info td { padding: 6px 10px; vertical-align: top; font-size: 13px; }
.ge-print table.info td.label { font-weight: bold; color: #555; width: 35%; }
.ge-print table.info td.value { color: #222; }
.ge-print .section-title { font-weight: bold; font-size: 13px; color: #1a3a5c; border-bottom: 2px solid #1a3a5c; padding-bottom: 3px; margin: 15px 0 8px; text-transform: uppercase; }
.ge-print table.items { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
.ge-print table.items th { background: #f0f4f8; padding: 6px 10px; text-align: left; font-size: 12px; border: 1px solid #ddd; color: #555; }
.ge-print table.items td { padding: 6px 10px; font-size: 12px; border: 1px solid #ddd; }
.ge-print .signatures { margin-top: 25px; }
.ge-print .signatures table { width: 100%; }
.ge-print .signatures td { text-align: center; padding-top: 30px; font-size: 12px; width: 33%; }
.ge-print .signatures .line { border-top: 1px solid #333; display: inline-block; width: 140px; margin-bottom: 3px; }
.ge-print .footer-note { text-align: center; margin-top: 15px; padding: 8px; background: #fff8e1; border: 1px dashed #f0ad4e; border-radius: 4px; font-size: 11px; color: #8a6d3b; }
</style>
<div class="ge-print">
<div class="header">
<h2>BETUL BIO FUEL PVT. LTD.</h2>
<p>GATE ENTRY — DETAILED</p>
</div>
<div class="subheader">
<h3>{{ doc.name }}</h3>
</div>
<div class="body">
<div class="section-title">Token & Vehicle Details</div>
<table class="info">
<tr><td class="label">Token Number:</td><td class="value">{{ doc.token_number or '' }}</td></tr>
<tr><td class="label">Vehicle Number:</td><td class="value">{{ token.vehicle_number if token else '' }}</td></tr>
<tr><td class="label">Vehicle Type:</td><td class="value">{{ doc.vehicle_type or '' }}</td></tr>
<tr><td class="label">Driver Name:</td><td class="value">{{ token.driver_name if token else '' }}</td></tr>
<tr><td class="label">Driver Mobile:</td><td class="value">{{ token.driver_mobile if token else '' }}</td></tr>
<tr><td class="label">Driver License:</td><td class="value">{{ token.driver_license_number if token else '' }}</td></tr>
</table>
<div class="section-title">Entry Details</div>
<table class="info">
<tr><td class="label">Entry Date:</td><td class="value">{{ frappe.format(doc.entry_date, {'fieldtype': 'Date'}) if doc.entry_date else '' }}</td></tr>
<tr><td class="label">Entry Time:</td><td class="value">{{ frappe.format(doc.entry_time, {'fieldtype': 'Time'}) if doc.entry_time else '' }}</td></tr>
<tr><td class="label">Material Flow:</td><td class="value">{{ doc.material_flow or '' }}</td></tr>
<tr><td class="label">Route To:</td><td class="value">{{ doc.route_to or '' }}</td></tr>
<tr><td class="label">Requires Weighing:</td><td class="value">{{ 'Yes' if doc.requires_weighing else 'No' }}</td></tr>
</table>
{% if doc.purchase_order %}
<div class="section-title">Purchase Order</div>
<table class="info">
<tr><td class="label">PO Number:</td><td class="value">{{ doc.purchase_order }}</td></tr>
<tr><td class="label">Supplier:</td><td class="value">{{ doc.supplier_name or '' }}</td></tr>
</table>
{% endif %}
{% if doc.po_items and doc.po_items|length > 0 %}
<div class="section-title">Material Items</div>
<table class="items">
<thead><tr><th>#</th><th>Item Code</th><th>Item Name</th><th>Qty</th><th>UOM</th></tr></thead>
<tbody>
{% for item in doc.po_items %}
<tr><td>{{ loop.index }}</td><td>{{ item.item_code or '' }}</td><td>{{ item.item_name or '' }}</td><td>{{ item.qty or '' }}</td><td>{{ item.uom or '' }}</td></tr>
{% endfor %}
</tbody>
</table>
{% endif %}
{% if doc.transporter %}
<div class="section-title">Transport</div>
<table class="info">
<tr><td class="label">Transporter:</td><td class="value">{{ doc.transporter }}</td></tr>
<tr><td class="label">LR Number:</td><td class="value">{{ doc.lr_number or '' }}</td></tr>
<tr><td class="label">LR Date:</td><td class="value">{{ frappe.format(doc.lr_date, {'fieldtype': 'Date'}) if doc.lr_date else '' }}</td></tr>
</table>
{% endif %}
<div class="section-title">Remarks</div>
<table class="info">
<tr><td class="value" style="min-height:40px;">{{ token.remarks if token and token.remarks else '—' }}</td></tr>
</table>
<div class="signatures">
<table><tr>
<td><div class="line"></div><br>G2 Gate Operator</td>
<td><div class="line"></div><br>Driver</td>
<td><div class="line"></div><br>Stores/Weighbridge</td>
</tr></table>
</div>
<div class="footer-note">⚠ This entry slip must accompany the vehicle at all times inside the plant.</div>
</div>
</div>
